def solve(grid):
    """Count number of islands in a binary grid (batch 2).
    An island is a group of adjacent 1's connected vertically or horizontally.
    Returns 0 for empty grid.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows or j < 0 or j >= cols:
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(rows):
