def solve(matrix):
    """Return elements of the matrix in clockwise spiral order.
    Handles empty matrix and non‑rectangular input safely.
    """
    if not matrix:
        return []
    # Ensure matrix is rectangular
    rows = len(matrix)
    cols = len(matrix[0]) if rows else 0
    # Validate all rows have same length; if not, treat missing entries as None
    for row in matrix:
        if len(row) != cols:
            raise ValueError('All rows must have the same length')
    result = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1
    while top <= bottom and left <= right:
        # top row
        for c in range(left, right + 1):
            result.append(matrix[top][c])
        top += 1
        # right column
        for r in range(top, bottom + 1):
            result.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for c in range(right, left - 1, -1):
                result.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            # left column
            for r in range(bottom, top - 1, -1):
                result.append(matrix[r][left])
            left += 1
    return result

